<?php
declare(strict_types=1);require dirname(__DIR__).'/lib/bootstrap.php';require dirname(__DIR__).'/lib/admin.php';require_admin();$pdo=db();$q=trim((string)($_GET['q']??''));$page=max(1,(int)($_GET['page']??1));$where='1';$params=[];if($q!==''){$where='item_name LIKE ? OR item_code LIKE ? OR shop_name LIKE ?';$params=array_fill(0,3,'%'.$q.'%');}$count=$pdo->prepare('SELECT COUNT(*) FROM items WHERE '.$where);$count->execute($params);$total=(int)$count->fetchColumn();$stmt=$pdo->prepare('SELECT * FROM items WHERE '.$where.' ORDER BY last_seen_at DESC LIMIT 50 OFFSET '.(($page-1)*50));$stmt->execute($params);$rows=$stmt->fetchAll();?><!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>商品管理</title><style>body{font-family:sans-serif;background:#f0f0f1}main{max-width:1200px;margin:auto}.box{background:#fff;padding:18px}table{width:100%;border-collapse:collapse}th,td{text-align:left;border-bottom:1px solid #ddd;padding:8px}img{width:64px;height:64px;object-fit:contain}input{padding:9px;width:min(500px,70%)}</style></head><body><main><p><a href="index.php">← 管理トップ</a></p><div class="box"><h1>商品管理</h1><form><input name="q" value="<?=h($q)?>" placeholder="商品名・商品コード・ショップ"><button>検索</button></form><p><?=number_format($total)?>件</p><table><thead><tr><th>画像</th><th>商品</th><th>価格</th><th>レビュー</th><th>ショップ</th><th>最終取得</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?php if($r['image_url']):?><img src="<?=h((string)$r['image_url'])?>" alt=""><?php endif?></td><td><a target="_blank" href="../public/item.php?id=<?=(int)$r['id']?>"><?=h((string)$r['item_name'])?></a><br><small><?=h((string)$r['item_code'])?></small></td><td>¥<?=number_format((int)$r['item_price'])?></td><td>★<?=number_format((float)$r['review_average'],2)?> (<?=number_format((int)$r['review_count'])?>)</td><td><?=h((string)$r['shop_name'])?></td><td><?=h((string)$r['last_seen_at'])?></td></tr><?php endforeach?></tbody></table><p><?php if($page>1):?><a href="?q=<?=urlencode($q)?>&page=<?=$page-1?>">←前へ</a><?php endif?> <?php if($page*50<$total):?><a href="?q=<?=urlencode($q)?>&page=<?=$page+1?>">次へ→</a><?php endif?></p></div></main></body></html>
